import {FilesetResolver,HandLandmarker} from 'https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/vision_bundle.mjs';
const canvas=document.querySelector('#art'),ctx=canvas.getContext('2d'),video=document.querySelector('#cam'),status=document.querySelector('#status');const sample=document.createElement('canvas');sample.width=100;sample.height=75;const sc=sample.getContext('2d',{willReadFrequently:true});let pixels,mask,hand=null,calm=0,particles=[],targets=[],lastTarget=0,alive=true,stream,model,lastHand=0,segmentBusy=false;const chars='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';const rand=(a,b)=>a+Math.random()*(b-a);function resize(){canvas.width=innerWidth;canvas.height=innerHeight}resize();addEventListener('resize',resize);addEventListener('keydown',e=>{if(e.code==='Digit2'&&!e.repeat)parent.postMessage('switch-mode','*')});
function open(h){const d=(a,b)=>Math.hypot(h[a].x-h[b].x,h[a].y-h[b].y);return [8,12,16,20].every(i=>d(i,0)>d(i-2,0)*1.1)}
const segment=new SelfieSegmentation({locateFile:f=>'https://cdn.jsdelivr.net/npm/@mediapipe/selfie_segmentation@0.1.1675465747/'+f});segment.setOptions({modelSelection:1});segment.onResults(r=>{sc.clearRect(0,0,100,75);sc.drawImage(r.segmentationMask,0,0,100,75);mask=sc.getImageData(0,0,100,75).data;sc.drawImage(video,0,0,100,75);pixels=sc.getImageData(0,0,100,75).data;segmentBusy=false});
function makeTargets(){targets=[];if(hand){const bones=[[0,1,2,3,4],[0,5,6,7,8],[5,9,10,11,12],[9,13,14,15,16],[13,17,18,19,20],[0,17],[5,17]];for(const chain of bones)for(let j=1;j<chain.length;j++){let a=hand[chain[j-1]],b=hand[chain[j]];for(let k=0;k<35;k++){let f=k/35;targets.push({x:(1-a.x-(b.x-a.x)*f)*canvas.width+rand(-8,8),y:(a.y+(b.y-a.y)*f)*canvas.height+rand(-8,8),l:220})}}}else if(mask&&pixels){for(let y=0;y<75;y++)for(let x=0;x<100;x++){let i=(x+y*100)*4;if(mask[i]>150){let l=(pixels[i]+pixels[i+1]+pixels[i+2])/3;targets.push({x:(1-x/100)*canvas.width,y:y/75*canvas.height,l})}}}}
let prev=performance.now();function draw(now){if(!alive)return;const dt=Math.min((now-prev)/16.67,2);prev=now;calm+=(Number(!!hand)-calm)*.035;ctx.fillStyle='#000';ctx.fillRect(0,0,canvas.width,canvas.height);if(calm>.01){let g=ctx.createLinearGradient(0,0,canvas.width,canvas.height);g.addColorStop(0,`rgba(255,116,146,${calm*.65})`);g.addColorStop(.4,`rgba(249,219,141,${calm*.6})`);g.addColorStop(.7,`rgba(84,188,171,${calm*.65})`);g.addColorStop(1,`rgba(177,145,211,${calm*.6})`);ctx.fillStyle=g;ctx.fillRect(0,0,canvas.width,canvas.height)}if(now-lastTarget>100){makeTargets();lastTarget=now}let desired=Math.min(3800,targets.length*1.4);while(particles.length<desired)particles.push({x:rand(0,canvas.width),y:rand(0,canvas.height),vx:0,vy:0,ch:chars[Math.floor(rand(0,chars.length))],drop:0,target:Math.random()});ctx.font='10px monospace';for(let i=particles.length-1;i>=0;i--){let q=particles[i],target=targets[Math.floor(q.target*targets.length)];if(hand)q.drop=0;else if(!q.drop&&Math.random()<.008)q.drop=1;if(target&&!q.drop){q.vx+=(target.x-q.x)*.018*dt;q.vy+=(target.y-q.y)*.018*dt;q.vx*=.79;q.vy*=.79}else{q.vy+=.19*dt;q.vx+=rand(-.12,.12)}q.x+=q.vx*dt;q.y+=q.vy*dt;if(q.y>canvas.height+20){q.y=rand(-80,0);q.x=target?.x??rand(0,canvas.width);q.vy=0;q.drop=0;q.ch=chars[Math.floor(rand(0,chars.length))]}ctx.fillStyle=hand?'rgba(255,255,255,.9)':`rgba(255,255,255,${target?.l? .3+target.l/365:.35})`;ctx.fillText(q.ch,q.x,q.y)}requestAnimationFrame(draw)}requestAnimationFrame(draw);
async function capture(){if(!alive)return;if(video.readyState>=2){try{if(!segmentBusy){segmentBusy=true;await segment.send({image:video})}if(model&&performance.now()-lastHand>150){lastHand=performance.now();let h=model.detectForVideo(video,lastHand).landmarks?.[0];hand=h&&open(h)?h:null}}catch(e){segmentBusy=false;status.textContent='Tracking interrupted. Press 2 to return and reopen.'}}setTimeout(capture,65)}
try{stream=await navigator.mediaDevices.getUserMedia({video:{width:480,height:360,facingMode:'user'},audio:false});video.srcObject=stream;await video.play();capture();const files=await FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/wasm');model=await HandLandmarker.createFromOptions(files,{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task'},runningMode:'VIDEO',numHands:1});status.textContent='';}catch(e){status.textContent='Allow camera access to form your portrait. Press 2 to return.'}addEventListener('pagehide',()=>{alive=false;stream?.getTracks().forEach(t=>t.stop());model?.close();segment.close()});
